      "most_likely_effort": 1.5
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Develop and Verify RxJava Processor Module (U6)",
      "activity_description": "Create and integrate the RxJava processor module with Spring Cloud Stream, validating reactive message passing and unit/integration tests.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Create Custom Shell Boot Banner (U7)",
